'use strict';
const fs=require('node:fs');const path=require('node:path');const crypto=require('node:crypto');const {Writable}=require('node:stream');
const allowed=['snipplets/product/payment-summary.tpl','snipplets/product/product-whatsapp.tpl','static/js/product-video-loading.js.tpl','static/js/product-payment-summary.js.tpl','static/js/product-whatsapp.js.tpl','static/css/product-commerce.css','static/css/product-whatsapp.css'];
const digest=b=>crypto.createHash('sha256').update(b).digest('hex');
async function readRemote(client,name){let chunks=[];await client.downloadTo(new Writable({write(c,e,cb){chunks.push(Buffer.from(c));cb();}}),name);return Buffer.concat(chunks);}
async function stage(client,root,files){let result=[];for(const name of files){if(!allowed.includes(name))throw Error('Unapproved dependency');let local=path.join(root,name),remote='/'+name,contents=fs.readFileSync(local),dir=path.posix.dirname(remote),base=path.posix.basename(remote);if(!contents.length||contents.length>2000000)throw Error('Invalid dependency size');let exists=(await client.list(dir)).some(x=>x.name===base);if(exists){if(digest(await readRemote(client,remote))!==digest(contents))throw Error('Unexpected existing dependency: '+name);}else{await client.uploadFrom(local,remote);if(digest(await readRemote(client,remote))!==digest(contents))throw Error('Dependency verification failed: '+name);}result.push(name);}return result;}
async function main(){const {execFileSync}=require('node:child_process');const before=process.env.BEFORE_SHA,after=process.env.AFTER_SHA;if(!/^[a-f0-9]{40}$/.test(before||'')||!(/^[a-f0-9]{40}$/.test(after||'')))throw Error('Missing commit bounds');const added=execFileSync('git',['diff','--name-only','--diff-filter=A',before,after],{encoding:'utf8'}).split(/\r?\n/).filter(x=>allowed.includes(x));if(!added.length){console.log('No new dependencies');return;}const {Client}=require('basic-ftp');const client=new Client(30000);try{await client.access({host:'ftp.nuvemshop.com.br',user:process.env.FTP_USER,password:process.env.FTP_PASSWORD,secure:true,secureOptions:{minVersion:'TLSv1.2'}});console.log('Verified new dependencies:',(await stage(client,process.cwd(),added)).length);}finally{client.close();}}
module.exports={stage};if(require.main===module)main().catch(e=>{console.error('Dependency stage failed:',e.message);process.exitCode=1});
